import{_ as d,a0 as o,w as n,s as p,I as a,x as i,a1 as u,A as r,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用 Audacity 录制音频（并降噪） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 Audacity 录制音频（并降噪） | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 Audacity 录制音频（并降噪） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 Audacity 录制音频（并降噪） | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-","title":"如何在 Linux 中使用 Audacity 录制音频（并降噪）","tag":"202211","desc":""},"relativePath":"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-.md","filePath":"[post].md"}'),l={name:"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-.md"};function y(f,t,b,g,c,m){const s=o("Link");return n(),p("div",null,[t[26]||(t[26]=a("h1",{id:"如何在-linux-中使用-audacity-录制音频-并降噪",tabindex:"-1"},[i("如何在 Linux 中使用 Audacity 录制音频（并降噪） "),a("a",{class:"header-anchor",href:"#如何在-linux-中使用-audacity-录制音频-并降噪","aria-label":"Permalink to “如何在 Linux 中使用 Audacity 录制音频（并降噪）”"},"​")],-1)),t[27]||(t[27]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/24/114858g6vpfg3gfglvxnp4.jpg",alt:""})],-1)),a("p",null,[u(s,{href:"https://github.com/audacity/audacity"},{default:r(()=>[...t[0]||(t[0]=[i("Audacity",-1)])]),_:1}),t[2]||(t[2]=i(" 是一个自由开源的跨平台 ",-1)),u(s,{href:"https://itsfoss.com/best-audio-editors-linux/"},{default:r(()=>[...t[1]||(t[1]=[i("音频编辑器",-1)])]),_:1}),t[3]||(t[3]=i("。专业人士使用它是因为它提供的功能仅需安装很小的软件包。",-1))]),t[28]||(t[28]=e('<p>你不必成为一名专业人士并使用它的所有功能。你可以使用它从麦克风录制音频，并执行一些基本操作，如背景噪声消除。</p><p>我将在本教程中向你展示如何做到这一点。</p><h3 id="在-linux-上安装-audacity" tabindex="-1">在 Linux 上安装 Audacity <a class="header-anchor" href="#在-linux-上安装-audacity" aria-label="Permalink to “在 Linux 上安装 Audacity”">​</a></h3><p>在 Linux 上安装 Audacity 是一个非常简单的过程。由于其受欢迎，可以在大多数 Linux 发行版的官方存储库中找到它。</p><p>你可以在发行版的软件中心或软件包管理器中搜索它。</p><p>作为一个终端爱好者，让我分享一下常见发行版的命令。</p><p>对于基于 Debian 或 Ubuntu 的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install audacity</span></span></code></pre></div><p>对于基于 RHEL 或 Fedora 的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install audacity</span></span></code></pre></div><p>如果你在用基于 Arch 的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Syu audacity</span></span></code></pre></div>',12)),a("p",null,[t[5]||(t[5]=a("strong",null,"注意",-1)),t[6]||(t[6]=i("，通过官方存储库安装可能无法获得 ",-1)),u(s,{href:"https://github.com/audacity/audacity/releases"},{default:r(()=>[...t[4]||(t[4]=[i("最新版本",-1)])]),_:1}),t[7]||(t[7]=i("。要获得最新版本，你可以使用 AppImage 或 Flatpak/Snap 软件包。",-1))]),t[29]||(t[29]=e('<h3 id="使用-audacity-录制音频" tabindex="-1">使用 Audacity 录制音频 <a class="header-anchor" href="#使用-audacity-录制音频" aria-label="Permalink to “使用 Audacity 录制音频”">​</a></h3><p>安装 Audacity 后，从应用程序菜单打开它或从终端启动它。你会看到这样的界面：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-interface.png" alt="Audacity Interface"></p><p>单击“录制”按钮（红点）即可轻松开始录制。完成后，单击“ 停止”按钮（方形图标）来结束录制。你还可以预览录制的波形，如下所示：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/record-audio-with-audacity.png" alt="record audio with audacity"></p><p>然后，你可以通过单击“播放”按钮（绿色图标）检查录制的内容。</p><p>如果你没有看到任何波形，则表示未录制到任何内容。很可能，你没有正确设置音频输入。确保你选择了正确的麦克风，并确保在“<ruby>系统设置<rt>system settings</rt></ruby>”中其未被静音。你也可以通过 Audacity 接口设置。</p><p>录音不会自动保存为 MP3 或其他格式。<strong>要保存录音</strong>，你可以转到 “<ruby>文件<rt>File</rt></ruby> → <ruby>导出<rt>Export</rt></ruby>” 并选择 “<ruby>导出为 MP3<rt>Export as MP3</rt></ruby>”（或任何其他想要的格式）。</p><h3 id="使用-audacity-降低背景噪声" tabindex="-1">使用 Audacity 降低背景噪声 <a class="header-anchor" href="#使用-audacity-降低背景噪声" aria-label="Permalink to “使用 Audacity 降低背景噪声”">​</a></h3><p>Audacity 还有另一个很棒的功能，你可以使用它来减少录制音频中的白噪声。</p><p>最好的做法是在开始使用 Audacity 录制时的前五秒不要说任何话。这将为你提供所需的背景噪声。</p><p>在录制音频的波形上，选择你认为是背景噪声的部分。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-reduction.png" alt="Background noise"></p><p>选择噪声部分后，从顶部文件菜单中转到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”。</p><p>它会像这样打开一个弹出窗口。单击此处的 “<ruby>获取噪音配置文件<rt>Get Noise Profile</rt></ruby>”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-steps.png" alt="Noise Reduction Effect Popup Window"></p><p>现在，你已经设置了噪声配置文件。现在，你必须使用它来减少录音中的噪声。</p><p>按 <code>Ctrl + A</code> 快捷键选择整段录音。你也可以选择其中的一部分，仅对所选部分减少噪声。</p><p>选择音轨后，再次转到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”。</p><p><strong>这次不要单击</strong> “<ruby>获取噪音配置文件<rt>Get Noise Profile</rt></ruby>”。这一次，你应该能够按下 “OK” 按钮。</p><p>只需按下 “OK” 按钮，即可将降噪效果应用到录音中，并反映在波形上，如下所示：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-reduced.png" alt="Audio Waveform after Noise Reduction"></p><p>现在，相较而言，录制的音频将具有更少的噪声。你可以在选择 “<ruby>降低噪音<rt>Noise Reduction</rt></ruby>” 效果时微调噪声过滤。</p><p>总结如下：</p><ul><li>选择噪声部分，转到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”，然后单击 “<ruby>获取噪音配置文件<rt>Get Noise Profile</rt></ruby>”</li><li>按 <code>Ctrl + A</code> 选择整段音频录制，转到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”，这次按 <code>OK</code> 按钮</li></ul><p>请注意，你无法移除所有类型的噪声，但这应该会有所帮助。</p><h3 id="audacity-能做更多事情" tabindex="-1">Audacity 能做更多事情 <a class="header-anchor" href="#audacity-能做更多事情" aria-label="Permalink to “Audacity 能做更多事情”">​</a></h3><p>使用 Audacity 录制音频可能不像使用 GNOME 录音机那样简单，但它并不太复杂。如果你正在录制画外音，降噪功能将非常有用。</p><p>Audacity 有更多其他功能，不可能在一个教程中涵盖所有这些功能。这就是为什么我会保持简短的原因。</p>',29)),a("p",null,[t[9]||(t[9]=i("如果你不能接受 2021 年的 ",-1)),u(s,{href:"https://news.itsfoss.com/audacity-fiasco-fork/"},{default:r(()=>[...t[8]||(t[8]=[i("Audacity 的隐私政策调整",-1)])]),_:1}),t[10]||(t[10]=i("，试试其他可用的工具。",-1))]),t[30]||(t[30]=a("p",null,"我希望这个小教程能帮助你使用 Audacity 进行音频录制。如果你有问题或建议，请告诉我。",-1)),t[31]||(t[31]=a("hr",null,null,-1)),a("p",null,[t[12]||(t[12]=i("via: ",-1)),u(s,{href:"https://itsfoss.com/audacity-recording/"},{default:r(()=>[...t[11]||(t[11]=[i("https://itsfoss.com/audacity-recording/",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=i("作者：",-1)),u(s,{href:"https://itsfoss.com/author/anuj/"},{default:r(()=>[...t[13]||(t[13]=[i("Anuj Sharma",-1)])]),_:1}),t[18]||(t[18]=i(" 选题：",-1)),u(s,{href:"https://github.com/lkxed"},{default:r(()=>[...t[14]||(t[14]=[i("lkxed",-1)])]),_:1}),t[19]||(t[19]=i(" 译者：",-1)),u(s,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:r(()=>[...t[15]||(t[15]=[i("FYJNEVERFOLLOWS",-1)])]),_:1}),t[20]||(t[20]=i(" 校对：",-1)),u(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=i("本文由 ",-1)),u(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[i("LCTT",-1)])]),_:1}),t[24]||(t[24]=i(" 原创编译，",-1)),u(s,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[i("Linux中国",-1)])]),_:1}),t[25]||(t[25]=i(" 荣誉推出",-1))])])}const k=d(l,[["render",y]]);export{x as __pageData,k as default};
